   fautes:[["^grid-template-columns ?: ?3 ?;?$","Un nombre seul ne suffit pas : repeat(3, 1fr)."],["^grid-columns","La propriété s'appelle grid-template-columns."],["^grid-template-rows","rows, ce sont les rangées. Pour les colonnes : columns."]],
