 lignes:[["print(\"Bonjour\")","affiche le texte Bonjour"],["print(\"Total :\", 1500)","plusieurs valeurs séparées par des virgules : Python met un espace entre elles"],["print()","une ligne vide"]],
 reponse:[["Bonjour","Le texte, sans les guillemets"],["Total : 1500","Le texte, un espace, puis le nombre"]],
 pieges:[["SyntaxError: Missing parentheses in call to 'print'. Did you mean print(...)?","Les parenthèses manquent : print(\"Bonjour\")."],["NameError: name 'Bonjour' is not defined","Les guillemets manquent autour du texte : sans eux, Python cherche une variable nommée Bonjour."],["NameError: name 'Print' is not defined. Did you mean: 'print'?","Python fait la différence entre majuscules et minuscules : print, en minuscules."]],
 mots:["string"],
 cherche:"afficher du texte ecrire a l'ecran montrer un resultat imprimer message",
