   fautes:[["^print ?[\"']","Il manque les parenthèses : print(\"Bonjour\")."],["^print\\( ?Bonjour ?\\)$","Il manque les guillemets : sans eux, Python cherche une variable nommée Bonjour."],["^Print\\(","Python fait la différence entre majuscules et minuscules : print, en minuscules."]],
