 lignes:[["az webapp log config --name mon-api-awa --resource-group mon-projet-rg --docker-container-logging filesystem","une seule fois : active les journaux"],["az webapp log tail --name mon-api-awa --resource-group mon-projet-rg","affiche le journal en direct"]],
