 lignes:[["import Carte from './Carte.jsx'","l'export default de Carte.jsx, rangé dans le même dossier"],["import { Bouton } from './Bouton.jsx'","un export nommé : entre accolades, avec son nom exact"],["import { useState } from 'react'","un outil de React : sans ./, car il vient des paquets installés"]],
